#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define MASK32 0xFFFFFFFFu
static uint32_t key[4];

static inline uint32_t expand_key(uint32_t k){
    k &= 0xFFFFF;
    return (k ^ (k<<16) ^ (k*12345u)) & MASK32;
}
static inline uint8_t g_function(uint8_t a,uint8_t b,uint8_t x){
    uint8_t t=(uint8_t)(a+b+x);
    return (uint8_t)((t<<2)|(t>>6));
}
static inline uint32_t f_function(uint32_t v){
    uint8_t x[4],y[4];
    for(int i=0;i<4;i++){x[i]=v&0xFF; v>>=8;}
    y[2]=g_function(x[3]^x[2], x[1]^x[0], 1);
    y[3]=g_function(x[3], y[2], 0);
    y[1]=g_function(x[1]^x[0], y[2], 0);
    y[0]=g_function(x[0], y[1], 1);
    uint32_t o=0;
    for(int i=0;i<4;i++) o |= ((uint32_t)y[i]) << (8*i);
    return o;
}
static inline uint8_t rotr2(uint8_t v){ return (uint8_t)((v>>2)|(v<<6)); }
static inline uint32_t f_inv(uint32_t yv){
    uint8_t y[4],x[4];
    for(int i=0;i<4;i++){y[i]=yv&0xFF; yv>>=8;}
    uint8_t x3 = (uint8_t)(rotr2(y[3]) - y[2]);
    uint8_t d  = (uint8_t)(rotr2(y[1]) - y[2]);          // x1^x0
    uint8_t e  = (uint8_t)(rotr2(y[2]) - d - 1);         // x3^x2
    uint8_t x2 = x3 ^ e;
    uint8_t x0 = (uint8_t)(rotr2(y[0]) - y[1] - 1);
    uint8_t x1 = d ^ x0;
    x[0]=x0;x[1]=x1;x[2]=x2;x[3]=x3;
    uint32_t o=0;
    for(int i=0;i<4;i++) o |= ((uint32_t)x[i]) << (8*i);
    return o;
}
static uint64_t encrypt_pt(uint64_t pt){
    uint32_t left=(uint32_t)(pt>>32), right=(uint32_t)pt;
    right ^= left;
    for(int r=0;r<4;r++){
        uint32_t mixed=f_function(right ^ key[r]);
        uint32_t t=right; right=left^mixed; left=t;
    }
    left ^= right;
    return ((uint64_t)right<<32)|left;
}

typedef struct { uint64_t k; uint32_t seed; } Ent;
static int cmp_ent(const void*a,const void*b){
    const Ent*x=a,*y=b;
    if(x->k<y->k) return -1; if(x->k>y->k) return 1; return 0;
}

#define NSEED (1u<<20)
static uint64_t pt[32], ct[32];
static uint32_t A_[32],B_[32],R3_[32],R4_[32];

int main(int argc,char**argv){
    // sanity check finv
    for(int t=0;t<100000;t++){
        uint32_t v=((uint32_t)rand()<<16)^rand();
        if(f_inv(f_function(v))!=v){printf("FINV FAIL %08x\n",v);return 1;}
    }
    FILE*fp=fopen("pairs.txt","r");
    if(!fp){perror("pairs");return 1;}
    int n=0; unsigned long long a,b;
    while(n<32 && fscanf(fp,"%llu %llu",&a,&b)==2){
        pt[n]=a; ct[n]=b;
        A_[n]=(uint32_t)(pt[n]>>32);
        uint32_t low=(uint32_t)pt[n];
        B_[n]=low ^ A_[n];
        R4_[n]=(uint32_t)(ct[n]>>32);
        uint32_t clow=(uint32_t)ct[n];
        R3_[n]=clow ^ R4_[n];
        n++;
    }
    fclose(fp);
    printf("read %d pairs\n",n);

    // build expand image lookup: sorted pairs (value, seed)
    Ent *img=malloc(sizeof(Ent)*NSEED);
    for(uint32_t s=0;s<NSEED;s++){ img[s].k=expand_key(s); img[s].seed=s; }
    qsort(img,NSEED,sizeof(Ent),cmp_ent);

    // build K0 table keyed by (P1,P2) using pairs 0,1
    Ent *tab=malloc(sizeof(Ent)*NSEED);
    for(uint32_t s0=0;s0<NSEED;s0++){
        uint32_t K0=expand_key(s0);
        uint32_t P1=0,P2=0;
        for(int j=0;j<2;j++){
            uint32_t u0=B_[j]^K0;
            uint32_t Fu0=f_function(u0);
            uint32_t R1=A_[j]^Fu0;
            uint32_t u2=f_inv(R3_[j]^A_[j]^Fu0);
            if(j==0){P1=R1;P2=u2;}
            else {P1^=R1;P2^=u2;}
        }
        tab[s0].k=((uint64_t)P1<<32)|P2;
        tab[s0].seed=s0;
    }
    qsort(tab,NSEED,sizeof(Ent),cmp_ent);
    printf("built K0 table\n");

    int found=0; uint32_t best[4]={0,0,0,0};
    for(uint32_t s3=0;s3<NSEED && !found;s3++){
        uint32_t K3=expand_key(s3);
        uint32_t Q1=0,Q2=0,u1_0=0,R2_0=0;
        for(int j=0;j<2;j++){
            uint32_t u3=R3_[j]^K3;
            uint32_t Fu3=f_function(u3);
            uint32_t u1=f_inv(R4_[j]^B_[j]^Fu3);
            uint32_t R2=B_[j]^f_function(u1);
            if(j==0){Q1=u1;Q2=R2;u1_0=u1;R2_0=R2;}
            else {Q1^=u1;Q2^=R2;}
        }
        uint64_t q=((uint64_t)Q1<<32)|Q2;
        // binary search range
        int lo=0,hi=(int)NSEED;
        while(lo<hi){int m=(lo+hi)/2; if(tab[m].k<q) lo=m+1; else hi=m;}
        for(int idx=lo; idx<(int)NSEED && tab[idx].k==q; idx++){
            uint32_t s0=tab[idx].seed;
            uint32_t K0=expand_key(s0);
            uint32_t u0=B_[0]^K0;
            uint32_t Fu0=f_function(u0);
            uint32_t R1=A_[0]^Fu0;
            uint32_t u2=f_inv(R3_[0]^A_[0]^Fu0);
            uint32_t K1=u1_0^R1;
            uint32_t K2=u2^R2_0;
            // check K1,K2 in expand image, get seeds
            // binary search img
            int l2=0,h2=(int)NSEED; while(l2<h2){int m=(l2+h2)/2; if(img[m].k<K1) l2=m+1; else h2=m;}
            if(l2>=(int)NSEED||img[l2].k!=K1) continue;
            uint32_t s1=img[l2].seed;
            l2=0;h2=(int)NSEED; while(l2<h2){int m=(l2+h2)/2; if(img[m].k<K2) l2=m+1; else h2=m;}
            if(l2>=(int)NSEED||img[l2].k!=K2) continue;
            uint32_t s2=img[l2].seed;
            // verify all pairs
            key[0]=expand_key(s0); key[1]=expand_key(s1); key[2]=expand_key(s2); key[3]=expand_key(s3);
            int ok=1;
            for(int j=0;j<n;j++){ if(encrypt_pt(pt[j])!=ct[j]){ok=0;break;} }
            if(ok){
                found=1; best[0]=s0;best[1]=s1;best[2]=s2;best[3]=s3;
                printf("FOUND seeds: %05x %05x %05x %05x\n",s0,s1,s2,s3);
                break;
            }
        }
    }
    if(!found){printf("NOT FOUND\n");return 1;}
    // emit key file
    FILE*kf=fopen("key.txt","w");
    fprintf(kf,"%05x %05x %05x %05x\n",best[0],best[1],best[2],best[3]);
    fclose(kf);
    printf("key written to key.txt\n");
    return 0;
}
